args.command:
mkdir -p /tmp/hashtest/src && cd /tmp/hashtest && cat > Cargo.toml <<'EOF'
[package]
name = "hashtest"
version = "0.1.0"
edition = "2021"
EOF
cat > src/main.rs <<'EOF'
use std::collections::HashSet;
use std::collections::hash_map::DefaultHasher;
use std::hash::BuildHasherDefault;

fn main() {
    let names = vec!["epsilon","five","two","six","gamma","kappa","eight","seven","delta","four","zeta","ten","alpha","iota","one","nine","eta","beta","theta","three"];
    // Try HashSet with BuildHasherDefault<DefaultHasher>
    let mut s: HashSet<String, BuildHasherDefault<DefaultHasher>> = Default::default();
    for n in &names { s.insert(n.to_string()); }
    let got: Vec<_> = s.iter().cloned().collect();
    println!("buildhasherdefault order: {:?}", got);
    let matches = got == names;
    println!("matches observed: {}", matches);
}
EOF
cargo run --release 2>&1 | tail -3

