args.command:
cd /tmp/hashtest && cat > src/main.rs <<'EOF'
use std::collections::hash_map::DefaultHasher;
use std::hash::{Hash, Hasher};

fn fnv1a(s: &str) -> u64 {
    let mut h: u64 = 0xcbf29ce484222325;
    for b in s.as_bytes() { h ^= *b as u64; h = h.wrapping_mul(0x100000001b3); }
    h
}
fn fxhash(s: &str) -> u64 {
    // rustc-hash FxHash style for str: processes bytes in chunks; approximate with simple version
    let mut h: u64 = 0;
    for b in s.as_bytes() { h = (h.rotate_left(5) ^ (*b as u64)).wrapping_mul(0x517cc1b727220a95); }
    h
}

fn main() {
    let observed = vec!["epsilon","five","two","six","gamma","kappa","eight","seven","delta","four","zeta","ten","alpha","iota","one","nine","eta","beta","theta","three"];
    // print DefaultHasher values in observed order to check monotonicity
    let mut prev = 0u64; let mut sorted_ok = true;
    for n in &observed {
        let mut h = DefaultHasher::new();
        n.hash(&mut h);
        let v = h.finish();
        println!("{:10} default={:016x} fnv={:016x} fx={:016x}", n, v, fnv1a(n), fxhash(n));
        if v < prev { sorted_ok = false; }
        prev = v;
    }
    println!("sorted by defaulthasher: {}", sorted_ok);
}
EOF
cargo run --release 2>&1 | tail -22

