args.command:
cd /tmp/hashtest && cat > src/main.rs <<'EOF'
use std::path::Path;
fn main() {
    for n in [".", "..", "a", "a.md", "a.md.md", "foo.txt", " ", ".md", "a.b.c"] {
        let mut p = Path::new("/base").join(n);
        let ok = p.set_extension("md");
        println!("{:>8} -> {:?} (set_ext returned {})", n, p, ok);
    }
    println!("file_name of /a/.: {:?}", Path::new("/a/.").file_name());
    println!("file_stem of .md: {:?}", Path::new(".md").file_stem());
    println!("file_stem of ' .md': {:?}", Path::new(" .md").file_stem());
    println!("extension of .jot: {:?}", Path::new(".jot").extension());
    println!("file_stem of .jot: {:?}", Path::new(".jot").file_stem());
}
EOF
cargo run --release 2>&1 | tail -15

